static bool same(const QString &a,const QString &b,const QString &type){if(type=="Real"||type=="Integer"||type=="Rvector"||type=="Rmatrix"||a.startsWith('[')&&b.startsWith('[')){auto parts=[](QString s){s.remove('[');s.remove(']');return s.split(QRegularExpression("[\\s,;]+"),Qt::SkipEmptyParts);};auto x=parts(a),y=parts(b);if(x.size()!=y.size())return false;for(int i=0;i<x.size();++i){bool ok=false,valid=false;double v=x[i].toDouble(&ok),w=y[i].toDouble(&valid);if(!ok||!valid||!std::isfinite(v)||!std::isfinite(w)||std::abs(v-w)>2e-11*std::max({1e-6,std::abs(v),std::abs(w)}))return false;}return true;}return a==b;}
